CREATE TABLE `ai_api_keys` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อ key สำหรับแสดงผล',
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ผู้ให้บริการ: grok, openai, gemini, groq, qwen, openrouter',
  `model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'โมเดลที่ใช้สำหรับ key นี้ (override default ของ provider)',
  `base_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Custom API base URL (override default — สำหรับ Xiaomi, custom proxy ฯลฯ)',
  `api_key` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API Key (encrypted)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'เปิด/ปิดใช้งาน',
  `is_critical` tinyint(1) NOT NULL DEFAULT '0' COMMENT '? critical (3 strikes failed health check) — ไม่ใช้อัตโนมัติ รอ admin ตรวจสอบ',
  `priority` int NOT NULL DEFAULT '0' COMMENT 'ลำดับความสำคัญ (สูง = ใช้ก่อน)',
  `purpose` enum('prediction','prediction_deep','prediction_celtic','free_card','chat','chat_paid','sensitive','tts') COLLATE utf8mb4_unicode_ci DEFAULT 'chat',
  `tokens_used_today` bigint NOT NULL DEFAULT '0' COMMENT 'Tokens ที่ใช้ไปวันนี้',
  `tokens_used_month` bigint NOT NULL DEFAULT '0' COMMENT 'Tokens ที่ใช้ไปเดือนนี้',
  `tokens_used_total` bigint NOT NULL DEFAULT '0' COMMENT 'Tokens ที่ใช้ไปทั้งหมด',
  `tokens_limit_daily` bigint DEFAULT NULL COMMENT 'จำกัด tokens/วัน (null = ไม่จำกัด)',
  `tokens_limit_monthly` bigint DEFAULT NULL COMMENT 'จำกัด tokens/เดือน (null = ไม่จำกัด)',
  `requests_today` int NOT NULL DEFAULT '0' COMMENT 'จำนวน requests วันนี้',
  `requests_minute` int NOT NULL DEFAULT '0' COMMENT 'จำนวน requests นาทีปัจจุบัน',
  `rate_limit_per_minute` int DEFAULT NULL COMMENT 'จำกัด requests/นาที',
  `last_rate_limit_reset` timestamp NULL DEFAULT NULL COMMENT 'เวลา reset rate limit ล่าสุด',
  `last_used_at` timestamp NULL DEFAULT NULL COMMENT 'ใช้งานล่าสุด',
  `consecutive_errors` int NOT NULL DEFAULT '0' COMMENT 'จำนวน errors ติดต่อกัน',
  `error_check_attempts` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่ลอง re-check หลัง disabled — 3 = critical',
  `last_health_check_at` timestamp NULL DEFAULT NULL COMMENT 'เวลา health check ล่าสุด',
  `last_test_passed_at` timestamp NULL DEFAULT NULL,
  `last_test_failed_at` timestamp NULL DEFAULT NULL,
  `last_test_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_recheck_at` timestamp NULL DEFAULT NULL COMMENT '? (2026-05-07) เวลา auto-recheck ครั้งล่าสุด',
  `recheck_failure_count` smallint unsigned NOT NULL DEFAULT '0' COMMENT '? (2026-05-07) จำนวน probe failure ติด — drives exponential backoff',
  `next_recheck_at` timestamp NULL DEFAULT NULL COMMENT '⏰ (2026-05-07) เวลา recheck ครั้งถัดไป — cron filter',
  `auto_recovered_at` timestamp NULL DEFAULT NULL COMMENT '? (2026-05-07) เวลา key auto-recover (สำหรับ admin alert + analytics)',
  `last_error` text COLLATE utf8mb4_unicode_ci COMMENT 'Error ล่าสุด',
  `last_error_at` timestamp NULL DEFAULT NULL COMMENT 'เวลา error ล่าสุด',
  `disabled_until` timestamp NULL DEFAULT NULL COMMENT 'ปิดใช้งานชั่วคราวจนถึง',
  `metadata` json DEFAULT NULL COMMENT 'ข้อมูลเพิ่มเติม (model preferences, etc.)',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'หมายเหตุ',
  `tokens_reset_date` date DEFAULT NULL COMMENT 'วันที่ reset tokens ล่าสุด',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ai_keys_provider_active_idx` (`provider`,`is_active`),
  KEY `ai_keys_active_priority_idx` (`is_active`,`priority`),
  KEY `ai_api_keys_provider_index` (`provider`),
  KEY `ai_api_keys_is_active_index` (`is_active`),
  KEY `ai_api_keys_is_critical_index` (`is_critical`),
  KEY `ai_api_keys_purpose_idx` (`purpose`),
  KEY `ai_api_keys_next_recheck_at_index` (`next_recheck_at`),
  KEY `ai_api_keys_last_test_passed_at_index` (`last_test_passed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
