  `feature_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'รหัสเฉพาะของ feature (เช่น ai_bot_marketplace)',
  `feature_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อ feature ภาษาไทย',
  `feature_name_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อ feature ภาษาอังกฤษ',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'คำอธิบาย feature',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'หมวดหมู่ (marketplace, generation, line_bot, automation, etc.)',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อไอคอน (FontAwesome หรือ custom)',
  `display_order` int NOT NULL DEFAULT '0' COMMENT 'ลำดับการแสดงผล',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'เปิด/ปิดใช้งานระบบทั้งหมด',
  `is_visible` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'แสดง/ซ่อนในเมนู',
  `requires_approval` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ต้องอนุมัติก่อนใช้งาน',
  `quota_type` enum('none','count','usage','duration','token') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none' COMMENT 'ประเภทโควต้า',
  `default_quota_limit` int DEFAULT NULL COMMENT 'จำนวนโควต้าเริ่มต้น',
  `quota_reset_period` enum('daily','weekly','monthly','yearly','never') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รอบการรีเซ็ตโควต้า',
  `pricing_tier` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ระดับราคา (free, basic, pro, enterprise)',
  `base_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ราคาฐาน (บาท/เดือน)',
  `usage_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ราคาต่อหน่วยการใช้งาน',
  `allowed_roles` json DEFAULT NULL COMMENT 'Roles ที่อนุญาตให้ใช้งาน',
  `required_permissions` json DEFAULT NULL COMMENT 'Permissions ที่ต้องมี',
  `config` json DEFAULT NULL COMMENT 'การตั้งค่าเพิ่มเติม (endpoints, API keys, etc.)',
  `metadata` json DEFAULT NULL COMMENT 'ข้อมูลเพิ่มเติม',
  `provider_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ผู้ให้บริการ AI (OpenAI, Google, etc.)',
  `provider_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เวอร์ชั่นของผู้ให้บริการ',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ai_core_features_feature_key_unique` (`feature_key`),
  KEY `ai_core_features_category_is_enabled_index` (`category`,`is_enabled`),
  KEY `ai_core_features_pricing_tier_is_enabled_index` (`pricing_tier`,`is_enabled`),
  KEY `ai_core_features_category_index` (`category`),
  KEY `ai_core_features_is_enabled_index` (`is_enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
