CREATE TABLE `ai_core_quotas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `feature_id` bigint unsigned NOT NULL,
  `period_type` enum('daily','weekly','monthly','yearly','lifetime') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ประเภทช่วงเวลา',
  `period_start` date NOT NULL COMMENT 'วันที่เริ่มต้น period',
  `period_end` date NOT NULL COMMENT 'วันที่สิ้นสุด period',
  `quota_limit` int NOT NULL COMMENT 'จำนวนโควต้าที่กำหนด',
  `quota_used` int NOT NULL DEFAULT '0' COMMENT 'จำนวนโควต้าที่ใช้ไปแล้ว',
  `quota_remaining` int GENERATED ALWAYS AS ((`quota_limit` - `quota_used`)) STORED COMMENT 'จำนวนโควต้าที่เหลือ',
  `allow_overage` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'อนุญาตให้เกินโควต้าได้',
  `overage_used` int NOT NULL DEFAULT '0' COMMENT 'จำนวนที่ใช้เกินโควต้า',
  `overage_price` decimal(10,4) DEFAULT NULL COMMENT 'ราคาต่อหน่วยที่เกิน',
  `bonus_quota` int NOT NULL DEFAULT '0' COMMENT 'โควต้าพิเศษที่ได้รับเพิ่ม',
  `bonus_reason` text COLLATE utf8mb4_unicode_ci COMMENT 'เหตุผลที่ได้โควต้าพิเศษ',
  `status` enum('active','expired','exhausted','suspended') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'สถานะโควต้า',
  `exhausted_at` timestamp NULL DEFAULT NULL COMMENT 'วันที่โควต้าหมด',
  `auto_reset` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'รีเซ็ตอัตโนมัติเมื่อครบ period',
  `next_reset_at` timestamp NULL DEFAULT NULL COMMENT 'วันที่จะรีเซ็ตครั้งถัดไป',
  `metadata` json DEFAULT NULL COMMENT 'ข้อมูลเพิ่มเติม',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quota_period_unique` (`tenant_id`,`feature_id`,`period_type`,`period_start`),
  KEY `ai_core_quotas_tenant_id_status_index` (`tenant_id`,`status`),
  KEY `ai_core_quotas_feature_id_period_type_index` (`feature_id`,`period_type`),
  KEY `ai_core_quotas_period_end_status_index` (`period_end`,`status`),
  KEY `ai_core_quotas_next_reset_at_index` (`next_reset_at`),
  KEY `ai_core_quotas_status_index` (`status`),
  CONSTRAINT `ai_core_quotas_feature_id_foreign` FOREIGN KEY (`feature_id`) REFERENCES `ai_core_features` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ai_core_quotas_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `ai_core_tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
