  `schedule_type` enum('once','recurring','cron') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'once' COMMENT 'ประเภท schedule',
  `starts_at` timestamp NULL DEFAULT NULL COMMENT 'วันเวลาเริ่มต้น (สำหรับ once)',
  `ends_at` timestamp NULL DEFAULT NULL COMMENT 'วันเวลาสิ้นสุด',
  `recurrence` enum('daily','weekly','monthly','yearly') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รูปแบบการทำซ้ำ',
  `recurrence_days` json DEFAULT NULL COMMENT 'วันที่ทำซ้ำ (เช่น [1,3,5] สำหรับ Mon,Wed,Fri)',
  `recurrence_time` time DEFAULT NULL COMMENT 'เวลาที่ทำซ้ำทุกวัน',
  `cron_expression` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Cron expression (เช่น 0 9 * * 1-5)',
  `timezone` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Asia/Bangkok' COMMENT 'Timezone สำหรับ schedule',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'เปิด/ปิด schedule นี้',
  `status` enum('pending','active','completed','failed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'สถานะ schedule',
  `last_executed_at` timestamp NULL DEFAULT NULL COMMENT 'ครั้งล่าสุดที่ทำงาน',
  `next_execution_at` timestamp NULL DEFAULT NULL COMMENT 'ครั้งถัดไปที่จะทำงาน',
  `execution_count` int NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่ทำงานแล้ว',
  `max_executions` int DEFAULT NULL COMMENT 'จำนวนครั้งสูงสุด (null = ไม่จำกัด)',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่ retry',
  `max_retries` int NOT NULL DEFAULT '3' COMMENT 'จำนวน retry สูงสุด',
  `last_error` text COLLATE utf8mb4_unicode_ci COMMENT 'Error ล่าสุด',
  `notify_on_execution` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'แจ้งเตือนเมื่อทำงาน',
  `notify_on_failure` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'แจ้งเตือนเมื่อล้มเหลว',
  `notification_channels` json DEFAULT NULL COMMENT 'ช่องทางแจ้งเตือน (email, line, etc.)',
  `metadata` json DEFAULT NULL COMMENT 'ข้อมูลเพิ่มเติม',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ai_core_schedules_created_by_foreign` (`created_by`),
  KEY `ai_core_schedules_feature_id_is_enabled_status_index` (`feature_id`,`is_enabled`,`status`),
  KEY `ai_core_schedules_tenant_id_is_enabled_index` (`tenant_id`,`is_enabled`),
  KEY `ai_core_schedules_next_execution_at_is_enabled_index` (`next_execution_at`,`is_enabled`),
  KEY `ai_core_schedules_is_enabled_index` (`is_enabled`),
  KEY `ai_core_schedules_status_index` (`status`),
  KEY `ai_core_schedules_next_execution_at_index` (`next_execution_at`),
  CONSTRAINT `ai_core_schedules_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ai_core_schedules_feature_id_foreign` FOREIGN KEY (`feature_id`) REFERENCES `ai_core_features` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ai_core_schedules_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `ai_core_tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
