  `marketplace_product_id` bigint unsigned NOT NULL COMMENT 'สินค้าที่เสนอ (marketplace_products.id)',
  `reading_id` bigint unsigned DEFAULT NULL COMMENT 'ผูกกับการดูดวงใบไหน (null = เสนอนอกรอบดูดวง)',
  `trigger` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'celtic_end | deep_end | chat_end | pitch_declined | customer_ask',
  `mu_group` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'กลุ่มสายมูที่เลือกมาเสนอ',
  `slot` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'low = ตัวเลือกราคาต่ำ | high = ตัวเลือกราคาสูง',
  `context_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ทำไมถึงเลือกชิ้นนี้ — ปีชง/ปีเกิด/ไพ่/สุ่ม (ไว้ debug)',
  `price_at_send` decimal(12,2) DEFAULT NULL COMMENT 'ราคา ณ ตอนส่ง (ราคาเปลี่ยนได้ทีหลัง)',
  `commission_rate_at_send` decimal(5,2) DEFAULT NULL COMMENT 'ค่าคอม %% ณ ตอนส่ง',
  `sent_at` timestamp NOT NULL COMMENT 'ส่งถึงลูกค้าเมื่อไหร่',
  `clicked_at` timestamp NULL DEFAULT NULL COMMENT 'ลูกค้ากดลิงก์เมื่อไหร่ (ถ้าติดตามได้)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fpo_user_sent_idx` (`platform`,`platform_user_id`,`sent_at`),
  KEY `fpo_user_product_idx` (`platform`,`platform_user_id`,`marketplace_product_id`),
  KEY `fpo_product_idx` (`marketplace_product_id`),
