  `facebook_post_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Post ID ที่คอมเมนต์',
  `questions` json NOT NULL COMMENT 'คำถามทั้งหมดที่ถาม (array of questions)',
  `categories` json DEFAULT NULL COMMENT 'หมวดหมู่ของคำถาม (array of category IDs)',
  `ai_response` longtext COLLATE utf8mb4_unicode_ci COMMENT 'คำทำนายจาก AI',
  `basic_response` longtext COLLATE utf8mb4_unicode_ci COMMENT 'คำทำนายพื้นฐาน',
  `deep_response` longtext COLLATE utf8mb4_unicode_ci COMMENT 'คำทำนายเชิงลึก',
  `user_profile` json DEFAULT NULL COMMENT 'ข้อมูลโปรไฟล์จาก Facebook Graph API',
  `user_posts_context` json DEFAULT NULL COMMENT 'โพสล่าสุดของผู้ใช้ (สำหรับวิเคราะห์บริบท)',
  `birth_date` date DEFAULT NULL COMMENT 'วันเดือนปีเกิดผู้ถาม เพื่อทำนายตามราศี/ลัคนา',
  `birth_time` time DEFAULT NULL COMMENT 'เวลาเกิด (ลูกค้าบอก/แอดมินกรอก) — NULL = ไม่ทราบ ใช้ 12:00 น.',
  `birth_time_source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ที่มาของ birth_time: default=ค่ามาตรฐาน 12:00 · customer=ลูกค้าบอก · admin=แอดมินกรอก · backfill=กู้ย้อนหลัง',
  `ai_provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI Provider ที่ใช้ (gemini, groq, qwen)',
  `ai_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI Model ที่ใช้',
  `tokens_used` int DEFAULT NULL COMMENT 'จำนวน tokens ที่ใช้',
  `is_paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ชำระเงินแล้วหรือยัง',
  `amount_paid` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'จำนวนเงินที่ชำระ',
  `partial_paid_total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `partial_target_total` decimal(10,2) DEFAULT NULL,
  `partial_rounds` tinyint unsigned NOT NULL DEFAULT '0',
  `partial_transrefs` json DEFAULT NULL,
  `partial_hold_at` timestamp NULL DEFAULT NULL,
  `amount_received` decimal(12,2) DEFAULT NULL COMMENT 'ยอดที่รับจริง (SlipOK/SMS/admin) — แยกจาก amount_paid ที่เป็นยอดบิลตั้งไว้',
  `payment_method` enum('qr_thai','stripe') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'qr_thai' COMMENT 'วิธีชำระเงิน: qr_thai=PromptPay ไทย / stripe=บัตรต่างประเทศ',
  `service_fee` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าบริการเพิ่มเติม (Stripe=15฿, QR Thai=0)',
  `stripe_session_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Stripe Checkout Session ID (cs_live_xxx / cs_test_xxx)',
  `stripe_payment_intent_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Stripe Payment Intent ID (pi_xxx) สำหรับ refund/dispute',
  `stripe_paid_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่ Stripe webhook confirm จ่ายสำเร็จ',
  `stripe_customer_region` enum('th','foreign') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ลูกค้าเลือก/Stripe detect: th=ในไทย ไม่บวกค่าบริการ, foreign=ต่างประเทศ +15฿',
  `transfer_reported` tinyint(1) NOT NULL DEFAULT '0',
  `transfer_reported_at` timestamp NULL DEFAULT NULL,
  `paid_at` timestamp NULL DEFAULT NULL COMMENT 'วันเวลาที่ชำระเงิน',
  `sms_notification_id` bigint unsigned DEFAULT NULL,
  `unique_payment_amount_id` bigint unsigned DEFAULT NULL,
  `sender_info` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ข้อมูลผู้โอน จาก SMS (ชื่อบัญชี/เลขอ้างอิง)',
  `sender_bank` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ธนาคารที่โอนเข้า',
  `is_floating` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'บิลลอย = ยังไม่ระบุตัวตนลูกค้า',
  `response_type` enum('comment','private_message') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'private_message' COMMENT 'ประเภทการตอบกลับ',
  `platform` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'facebook',
  `platform_user_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fortune_page_id` bigint unsigned DEFAULT NULL COMMENT 'สาขา/เพจที่เป็นต้นทางของแถวนี้ (fortune_pages.id)',
  `reading_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'basic' COMMENT 'ประเภทคำทำนาย: basic = พื้นฐาน, deep = เชิงลึก',
  `conversation_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new',
  `conversation_state` longtext COLLATE utf8mb4_unicode_ci,
  `admin_takeover_until` timestamp NULL DEFAULT NULL COMMENT 'เวลาหมดเทคโอเวอร์ — AI กลับมาทำงานหลังเวลานี้',
  `admin_takeover_by` bigint unsigned DEFAULT NULL COMMENT 'user_id ของแอดมินที่เทคโอเวอร์',
  `admin_takeover_reason` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เหตุผล: manual=กดเทค, auto_reply=แอดมินพิมพ์, customer_request=ลูกค้าขอ',
  `admin_takeover_started_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาเริ่มเทคโอเวอร์ครั้งล่าสุด',
  `reading_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL รูปคำทำนายที่สร้างส่งให้ผู้ใช้',
  `celtic_summary_image_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path ภาพ composite Celtic Cross spread (storage/app/public)',
  `celtic_questions_used` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'จำนวนคำถามที่ใช้ไปแล้ว (0-3)',
  `celtic_first_answered_at` timestamp NULL DEFAULT NULL COMMENT 'Timestamp ที่ Q1 ตอบเสร็จ — ใช้คำนวณ 1 ชม. window',
  `user_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL รูปที่ผู้ใช้ส่งมาผ่าน Messenger',
  `responded_at` timestamp NULL DEFAULT NULL COMMENT 'วันเวลาที่ตอบกลับ',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่ดูผลการทำนาย',
  `rating` int DEFAULT NULL COMMENT 'คะแนนความพึงพอใจ (1-5)',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT 'ความคิดเห็นจากผู้ใช้',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `voice_audio_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Random 32-char token สำหรับ public URL (กัน enumeration)',
  `voice_audio_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Relative path ใน storage/app/public — เช่น fortune-voice/{token}.mp3',
  `voice_audio_disk` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Driver ที่ใช้เซฟ audio นี้ (สำหรับ migration tool)',
  `voice_audio_url` text COLLATE utf8mb4_unicode_ci COMMENT 'Full URL ของ audio (โดยเฉพาะ Firebase ที่ต้องมี token ใน URL)',
  `voice_audio_duration_ms` int DEFAULT NULL COMMENT 'ระยะเวลา audio (ms) — ใช้ส่งใน LINE message',
  `voice_audio_provider` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Provider ที่ generate: minimax / google_tts / openai_tts / gtts',
  `voice_audio_chars` int DEFAULT NULL COMMENT 'จำนวน chars ที่ synthesize (cost tracking)',
  `voice_audio_generated_at` timestamp NULL DEFAULT NULL COMMENT 'เวลา generate สำเร็จ',
  `fuzzy_approved_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่ bot อนุมัติ fuzzy match',
  `fuzzy_approved_delta` decimal(6,2) DEFAULT NULL COMMENT 'ส่วนต่าง (positive=เกิน, negative=ขาด)',
  `fuzzy_approved_sms_id` bigint unsigned DEFAULT NULL COMMENT 'SmsPaymentNotification.id ที่จับคู่',
  `fuzzy_approved_name_score` tinyint unsigned DEFAULT NULL COMMENT '% similar_text ของชื่อผู้โอน vs Facebook name',
  `slip_image_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'สลิปที่ลูกค้าส่ง (รอ verify fallback) — ลบหลังตรวจเสร็จ',
  `slip_received_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่รับสลิปจากลูกค้า',
  `slipok_verified_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่ SlipOK อนุมัติบิลนี้',
  `slipok_trans_ref` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เลขอ้างอิงรายการ (transRef) จาก SlipOK',
  PRIMARY KEY (`id`),
