DROP TABLE IF EXISTS `fortune_sensitive_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fortune_sensitive_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `platform` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'facebook / line',
  `platform_user_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FB PSID / LINE userId',
  `user_id` bigint unsigned DEFAULT NULL COMMENT 'users.id ถ้า map ได้',
  `context` enum('chat','deep_question','celtic_turn','free_card') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'บริบทที่ trigger',
  `is_sensitive` tinyint(1) NOT NULL DEFAULT '0',
  `is_offtopic` tinyint(1) NOT NULL DEFAULT '0',
  `mood_level` tinyint DEFAULT NULL COMMENT '1-5 (5=ก้าวร้าวสุด)',
  `complexity` tinyint DEFAULT NULL COMMENT '1-5 (5=ซับซ้อนสุด)',
  `reasons` json DEFAULT NULL COMMENT 'Array ของ trigger reasons',
  `detection_used` enum('heuristic','classifier','hybrid') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `used_pro_model` tinyint(1) NOT NULL DEFAULT '0',
  `pro_provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pro_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `budget_blocked` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ถูก block เพราะเกิน budget',
  `offtopic_blocked` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ถูก block เพราะ off-topic',
  `message_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SHA-256 ของข้อความ (dedupe)',
  `message_preview` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '60 chars แรก (debug)',
  `message_length` int DEFAULT NULL,
  `tokens_used` int DEFAULT NULL,
  `cost_thb` decimal(8,4) DEFAULT NULL COMMENT 'ประมาณการต้นทุน THB',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fortune_sensitive_events_platform_platform_user_id_index` (`platform`,`platform_user_id`),
  KEY `fortune_sensitive_events_user_id_created_at_index` (`user_id`,`created_at`),
  KEY `fortune_sensitive_events_context_created_at_index` (`context`,`created_at`),
  KEY `fortune_sensitive_events_is_sensitive_index` (`is_sensitive`),
  KEY `fortune_sensitive_events_used_pro_model_index` (`used_pro_model`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
