  `fuzzy_underpay_max_baht` decimal(6,2) NOT NULL DEFAULT '1.00' COMMENT 'รับขาดได้กี่บาท (default 1 — เผื่อตัดเศษทศนิยม)',
  `fuzzy_window_minutes` int unsigned NOT NULL DEFAULT '60' COMMENT 'ช่วงเวลา SMS หลังสร้างบิล (default 60 = อายุ UPA)',
  `fuzzy_name_auto_threshold` tinyint unsigned NOT NULL DEFAULT '70' COMMENT '% similar_text ที่ถือว่าชื่อตรงพอ auto (default 70%)',
  `fuzzy_admin_alert_above_baht` decimal(6,2) NOT NULL DEFAULT '5.00' COMMENT 'แจ้งแอดมิน LINE OA ถ้า delta > นี้ (default 5)',
  `voice_storage_driver` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local' COMMENT 'Driver ที่ใช้เก็บไฟล์เสียง: local / r2 / s3 / gcs / firebase',
  `voice_storage_config` json DEFAULT NULL COMMENT 'JSON: per-driver config (credentials + bucket + public URL)',
  `system_voice_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'master toggle ส่งเสียงระบบ (กล่องกระตุ้น/กติกา/วันเกิด ฯลฯ) — FB เท่านั้น',
  `celtic_pick_voice_delay_sec` int unsigned NOT NULL DEFAULT '45' COMMENT 'หน่วงเวลา(วินาที)ก่อนเล่นเสียงเลือกไพ่ใบต่อไป (เงียบเกินนี้ค่อยเล่น) 0=ปิด',
  `message_debounce_seconds` tinyint unsigned NOT NULL DEFAULT '3' COMMENT 'Debounce window สำหรับรวมข้อความที่ลูกค้าพิมพ์ติด ๆ (0=ปิด, 1-30 วินาที)',
  `enable_slipok_verify` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'เปิดใช้ SlipOK ตรวจสลิป (fallback เมื่อ SMS checker ไม่พบ)',
  `slipok_branch_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SlipOK Branch ID (ใส่ใน URL path)',
  `slipok_api_key` text COLLATE utf8mb4_unicode_ci COMMENT 'SlipOK API Key (header x-authorization) — encrypted',
  `slipok_min_amount` decimal(8,2) NOT NULL DEFAULT '99.00' COMMENT 'ยอดขั้นต่ำที่อนุมัติ (ไม่ต่ำกว่านี้) default 99',
  `slipok_fallback_delay_seconds` int unsigned NOT NULL DEFAULT '60' COMMENT 'หน่วงก่อนเช็ค fallback (วินาที) default 60',
  `slipok_use_log` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'ส่ง log=true ให้ SlipOK (dedup + เช็คบัญชีผู้รับ)',
  `slipok_pool_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `slipok_pool_mode` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'near_empty',
  `slipok_pool_threshold` int unsigned NOT NULL DEFAULT '10',
  `slipok_max_checks_per_user` smallint unsigned DEFAULT '2' COMMENT 'เพดานยิง SlipOK ต่อคน/หน้าต่าง (กัน flood ดูดโควต้า) — 0 = ไม่จำกัด',
  `slipok_check_window_hours` smallint unsigned DEFAULT '24' COMMENT 'ความยาวหน้าต่างเวลานับเพดานยิง SlipOK (ชั่วโมง)',
  `slipok_ban_after_rounds` smallint unsigned DEFAULT '2' COMMENT 'ก่อกวนเกินเพดานกี่รอบแล้วแบนอัตโนมัติ — 0 = ไม่แบนอัตโนมัติ',
  `slipok_auto_provision` tinyint(1) DEFAULT '1' COMMENT 'โอนก่อนสร้างบิล/QR → สลิปจริง+เข้าบัญชีเรา+ยอดครบ → สร้างบิล Celtic+เปิดไพ่เอง (ไม่ต้องรอแอดมิน)',
  `enable_celtic_patterns` tinyint(1) NOT NULL DEFAULT '1',
  `enable_celtic_dignity` tinyint(1) NOT NULL DEFAULT '1',
  `enable_celtic_dynamics` tinyint(1) NOT NULL DEFAULT '1',
  `enable_celtic_yesno` tinyint(1) NOT NULL DEFAULT '1',
  `fortune_consent_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `fortune_consent_pick_strategy` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'random',
  `fortune_consent_text` text COLLATE utf8mb4_unicode_ci,
  `fortune_consent_cancel_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `fortune_consent_cancel_text` text COLLATE utf8mb4_unicode_ci,
  `fortune_consent_expire_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `fortune_consent_expire_text` text COLLATE utf8mb4_unicode_ci,
  `enable_celtic_birthdate_first` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Celtic 99: ถามวันเกิดเป็นคำถามแรก + ทำนายพื้นดวง (ดาวเจ้าชนะ) ผสมไพ่',
  `enable_kbank_verify` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'เปิดตรวจสลิปด้วย KBank API',
  `kbank_env` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sandbox' COMMENT 'sandbox|production',
  `kbank_base_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'override base URL (ปกติเว้นว่าง)',
  `kbank_verify_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เช่น /v1/verslip/kbank/verify',
  `kbank_consumer_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Consumer ID / Key จาก KBank API Portal',
  `kbank_consumer_secret` text COLLATE utf8mb4_unicode_ci COMMENT 'Consumer Secret (เข้ารหัสเก็บ)',
  `kbank_cert_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'path ไฟล์ client cert (.pem/.crt)',
  `kbank_cert_key_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'path ไฟล์ private key (.key)',
  `kbank_cert_password` text COLLATE utf8mb4_unicode_ci COMMENT 'passphrase ของ private key (เข้ารหัสเก็บ)',
  `kbank_min_amount` decimal(10,2) NOT NULL DEFAULT '99.00' COMMENT 'ยอดขั้นต่ำที่อนุมัติ',
  `enable_web_fortune_button` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'เปิดปุ่มดูดวงฟรีบนเว็บ (magic link)',
  `web_fortune_sso_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'override URL SSO เว็บจันทรา (ปกติเว้นว่าง)',
  `fortune_bot_mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'classic' COMMENT 'classic = โฟลเดิม · transfer = ดักหน้าแชท FB พาไปเว็บ/LINE',
  `transfer_box_cooldown_hours` smallint unsigned NOT NULL DEFAULT '24',
  `transfer_fallback_attempts` tinyint unsigned NOT NULL DEFAULT '3',
  `transfer_fallback_days` smallint unsigned NOT NULL DEFAULT '30',
  `transfer_rollout_percent` tinyint unsigned NOT NULL DEFAULT '100',
  `free_card_max_chars` smallint unsigned NOT NULL DEFAULT '0',
  `free_card_regrant_at` timestamp NULL DEFAULT NULL COMMENT 'เลื่อนเวลานี้ = แจกสิทธิ์ดูฟรีใหม่ให้ทุกคน',
  `admin_notify_psid` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PSID แอดมินที่รับแจ้งเตือน — หลายคนคั่นด้วย , (comma)',
  `admin_notify_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'เปิด/ปิดการแจ้งเตือนแอดมินทาง Messenger',
  `comment_flood_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'เปิดระบบจับคอมเมนต์รัวในโพสต์เดียว',
  `comment_flood_threshold` smallint unsigned NOT NULL DEFAULT '5' COMMENT 'คอมเมนต์ในโพสต์เดียวเกินกี่ครั้งถึงถือว่าสแปม (เกินค่านี้ = โดน)',
  `comment_flood_window_minutes` smallint unsigned NOT NULL DEFAULT '60' COMMENT 'กรอบเวลานับคอมเมนต์รัว (นาที) — เกิน threshold ภายในกรอบนี้ = สแปม',
  `comment_flood_action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'notify' COMMENT 'notify = แค่เตือน ไม่บล็อก (default) / block = บล็อกทันที',
  `comment_flood_sustain_buckets` smallint unsigned NOT NULL DEFAULT '10' COMMENT 'คอมเมนต์กี่ "ช่วง 10 นาที" ภายใน 3 ชม. ถึงถือว่าคอมตลอดเวลา (ผิดปกติ)',
  `facebook_user_token` text COLLATE utf8mb4_unicode_ci,
  `facebook_user_token_checked_at` timestamp NULL DEFAULT NULL,
  `facebook_user_token_expires_at` timestamp NULL DEFAULT NULL,
  `facebook_user_token_data_access_expires_at` timestamp NULL DEFAULT NULL,
  `enable_nav_flood_guard` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'เปิดระบบเบรกกดปุ่มรัว (ปิดไว้ก่อน ต้อง shadow mode ก่อนเปิด)',
  `nav_flood_mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'log_only' COMMENT 'log_only = คำนวณครบแต่ไม่บล็อกใคร | enforce = บังคับใช้จริง',
  `nav_flood_repeat_max` tinyint unsigned NOT NULL DEFAULT '4' COMMENT 'ปุ่มเดิมกดซ้ำกี่ครั้งถึงนับเป็นความผิด',
  `nav_flood_repeat_window_sec` smallint unsigned NOT NULL DEFAULT '120' COMMENT 'หน้าต่างเวลาของกฎปุ่มเดิม (วินาที)',
  `nav_flood_rate_max` tinyint unsigned NOT NULL DEFAULT '15' COMMENT 'ปุ่มใดก็ได้รวมกันกี่ครั้งถึงนับเป็นความผิด',
  `nav_flood_rate_window_sec` smallint unsigned NOT NULL DEFAULT '300' COMMENT 'หน้าต่างเวลาของกฎรวม (วินาที)',
  `nav_flood_same_payload_lock_sec` smallint unsigned NOT NULL DEFAULT '25' COMMENT 'เบรกเงียบ: ปุ่มเดิมกดซ้ำภายในกี่วินาที = ไม่ตอบ (ไม่นับความผิด)',
  `nav_flood_cooldown_minutes` smallint unsigned NOT NULL DEFAULT '5' COMMENT 'เตือนครั้งแรกแล้วเงียบกี่นาที',
  `nav_flood_ban_days` tinyint unsigned NOT NULL DEFAULT '7' COMMENT 'ระงับการใช้งานกี่วันเมื่อครบ 3 strikes',
  `entry_cards_on_dm` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'DM ตอบคอมเมนต์เป็นการ์ด 2 ใบ (ฟรี/VIP)',
  `birth_day_cards_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ถามวันเกิดด้วยการ์ด 7 วันมีรูป แทนปุ่มข้อความ',
  `entry_cards_on_chat` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'ลูกค้าพิมพ์ขอดวงรายวัน/ขอดูฟรี → ตอบเป็นการ์ด 2 ใบ (ฟรี/VIP)',
  `fortune_chat_bubbles_fb` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'FB: ตอบคำทำนายเป็นหลายกล่อง เว้นระยะเหมือนคนพิมพ์',
  `fortune_chat_bubbles_line` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'LINE: แยกกล่อง (default ปิด — กล่อง 2..N กินโควตา push)',
  `fortune_chat_bubble_gap_min` smallint unsigned NOT NULL DEFAULT '5' COMMENT 'ระยะห่างต่ำสุดระหว่างกล่อง (วินาที)',
  `fortune_chat_bubble_gap_max` smallint unsigned NOT NULL DEFAULT '10' COMMENT 'ระยะห่างสูงสุดระหว่างกล่อง (วินาที)',
  `fortune_chat_bubble_max` tinyint unsigned NOT NULL DEFAULT '4' COMMENT 'จำนวนกล่องมากสุดต่อ 1 คำตอบ',
  `celtic_qa_settle_seconds` smallint unsigned NOT NULL DEFAULT '10' COMMENT 'Celtic Q&A: รอกี่วินาทีหลังลูกค้าหยุดพิมพ์ ก่อนรวบตอบ (0 = ปิด)',
  `pro_session_settle_seconds` smallint unsigned NOT NULL DEFAULT '10' COMMENT 'Pro Session / Deep 39: รอกี่วินาทีหลังลูกค้าหยุดพิมพ์ ก่อนรวบตอบ (0 = ปิด)',
  `qa_settle_ramble_seconds` smallint unsigned NOT NULL DEFAULT '50' COMMENT 'คนเล่ายาว: ขยายหน้าต่างรอเป็นกี่วินาที (0 = ไม่ขยาย ใช้ค่าพื้นฐาน)',
  `qa_settle_max_seconds` smallint unsigned NOT NULL DEFAULT '180' COMMENT 'เพดานรวมนับจากข้อความแรกในชุด — ครบแล้วตอบทันทีแม้ยังพิมพ์อยู่',
  `qa_ramble_brief_reply` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'คนเล่ายาว: ตอบสั้นรับฟัง 2-3 บรรทัด แทนคำทำนายเต็ม',
  PRIMARY KEY (`id`),
  KEY `fortune_settings_enabled_idx` (`is_enabled`),
  KEY `fk_settings_sensitive_key` (`sensitive_ai_pool_key_id`),
  CONSTRAINT `fk_settings_sensitive_key` FOREIGN KEY (`sensitive_ai_pool_key_id`) REFERENCES `ai_api_keys` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
