CREATE TABLE `fortune_user_bans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `platform` enum('facebook','line') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'แพลตฟอร์มที่ถูกแบน',
  `platform_user_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PSID (Facebook) หรือ LINE userId',
  `display_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อที่แสดงตอนแบน (snapshot)',
  `reason` text COLLATE utf8mb4_unicode_ci COMMENT 'เหตุผลที่แบน (สำหรับ audit)',
  `banned_until` timestamp NULL DEFAULT NULL COMMENT 'NULL = ถาวร, อนาคต = แบนถึงเวลานี้',
  `banned_by` bigint unsigned DEFAULT NULL,
  `last_notified_at` timestamp NULL DEFAULT NULL COMMENT 'ครั้งล่าสุดที่ส่งข้อความแจ้งสถานะแบน',
  `notify_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่แจ้งสถานะ (ใช้ตรวจ spam)',
  `attempt_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่ user พยายามทักหลังถูกแบน',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `fortune_page_id` bigint unsigned DEFAULT NULL COMMENT 'สาขา/เพจที่เป็นต้นทางของแถวนี้ (fortune_pages.id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `fortune_user_bans_unique_user` (`platform`,`platform_user_id`),
  KEY `fortune_user_bans_banned_by_foreign` (`banned_by`),
  KEY `fortune_user_bans_until_idx` (`banned_until`),
  KEY `ftn_pg_2f27bab0cf173f79842b14e_idx` (`fortune_page_id`),
  CONSTRAINT `fortune_user_bans_banned_by_foreign` FOREIGN KEY (`banned_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
