CREATE TABLE `fortune_user_credits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `facebook_user_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `facebook_user_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_dm_at` timestamp NULL DEFAULT NULL,
  `last_dm_at` timestamp NULL DEFAULT NULL,
  `dm_count` int unsigned NOT NULL DEFAULT '0',
  `last_warmup_sent_at` timestamp NULL DEFAULT NULL,
  `last_dm_image_at` timestamp NULL DEFAULT NULL COMMENT '? (2026-06-06) เวลาที่ส่งรูปแบนเนอร์ใน DM ล่าสุด — ใช้กันส่งรูปซ้ำในสัปดาห์เดียวกัน',
  `dm_snooze_until` timestamp NULL DEFAULT NULL COMMENT '? (2026-06-06) พัก DM ตาม comment/reaction จนถึงเวลานี้ (ปุ่ม "พัก 7 วัน")',
  `dm_opted_out_at` timestamp NULL DEFAULT NULL COMMENT '? (2026-06-06) ลูกค้ากด "ไม่ต้องส่งอีก" — หยุด DM ตาม comment/reaction ถาวร (null = ปกติ)',
  `facebook_follow_prompted_at` timestamp NULL DEFAULT NULL,
  `facebook_followed_confirmed_at` timestamp NULL DEFAULT NULL,
  `facebook_group_clicked_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่ user คลิกปุ่มเข้ากลุ่ม (tracking redirect)',
  `platform` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'facebook',
  `bonus_credits` int NOT NULL DEFAULT '0' COMMENT 'เครดิตดูดวงฟรีที่ได้รับ (เพิ่มเติมจากสิทธิ์ประจำวัน)',
  `credits_used` int NOT NULL DEFAULT '0' COMMENT 'เครดิตที่ใช้ไปแล้ว',
  `is_unlimited` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ดูดวงฟรีไม่จำกัด',
  `unlimited_until` date DEFAULT NULL COMMENT 'ดูฟรีไม่จำกัดจนถึงวันที่',
  `is_daily_reset` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'รีเซ็ตสิทธิ์ฟรีวันนี้ (ไม่นับใช้ไปแล้ววันนี้)',
  `daily_reset_date` date DEFAULT NULL COMMENT 'วันที่รีเซ็ตล่าสุด',
  `note` text COLLATE utf8mb4_unicode_ci COMMENT 'หมายเหตุจากแอดมิน',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT 'แอดมินที่แก้ไขล่าสุด',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `transfer_box_sent_at` timestamp NULL DEFAULT NULL,
  `transfer_attempts` smallint unsigned NOT NULL DEFAULT '0',
  `fb_fallback_granted_at` timestamp NULL DEFAULT NULL COMMENT 'ลูกค้ายืนยันขอดูดวงในแชท FB (ทำเว็บ/ไลน์ไม่ได้)',
  `birth_date` date DEFAULT NULL COMMENT 'วันเดือนปีเกิดเต็ม (ได้จากโหมด DM ดูดวงรายวัน)',
  `birth_day` tinyint unsigned DEFAULT NULL COMMENT 'วันเกิดในสัปดาห์ 0=อาทิตย์ … 6=เสาร์ (ตรงกับ horoscope_daily_predictions.birth_day)',
  `birth_date_source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ที่มา: daily_dm_button | daily_dm_text',
  `birth_date_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่ได้ข้อมูลวันเกิดมา',
  `daily_dm_asked_at` timestamp NULL DEFAULT NULL COMMENT 'ส่ง DM ชวนบอกวันเกิดครั้งล่าสุดเมื่อไหร่',
  `daily_dm_answered_at` timestamp NULL DEFAULT NULL COMMENT 'ลูกค้าตอบวันเกิดกลับมาครั้งล่าสุดเมื่อไหร่',
  `fortune_page_id` bigint unsigned DEFAULT NULL COMMENT 'สาขา/เพจที่เป็นต้นทางของแถวนี้ (fortune_pages.id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `fortune_user_credits_unique` (`facebook_user_id`,`platform`),
  KEY `fortune_user_credits_facebook_user_id_index` (`facebook_user_id`),
  KEY `fortune_user_credits_last_dm_at_idx` (`last_dm_at`),
  KEY `fortune_user_credits_facebook_group_clicked_at_index` (`facebook_group_clicked_at`),
  KEY `ftn_pg_9dc00946bda4e348ea1feba_idx` (`fortune_page_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
