CREATE TABLE `service_bookings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `booking_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'เลขที่จอง เช่น SB-20251124-0001',
  `user_id` bigint unsigned NOT NULL,
  `service_id` bigint unsigned DEFAULT NULL,
  `package_id` bigint unsigned DEFAULT NULL,
  `provider_id` bigint unsigned DEFAULT NULL,
  `scheduled_at` datetime NOT NULL COMMENT 'วันเวลานัดหมาย',
  `service_duration_minutes` int NOT NULL DEFAULT '60' COMMENT 'ระยะเวลาให้บริการ (นาที)',
  `base_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ราคาบริการ',
  `distance_km` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT 'ระยะทางจริง (km)',
  `distance_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าเดินทาง',
  `options_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าออฟชั่นเพิ่มเติม',
  `subtotal` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'รวมย่อย',
  `tax_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ภาษี VAT 7%',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ส่วนลด',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ราคารวมสุทธิ',
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'วิธีชำระเงิน: wallet, promptpay, card',
  `payment_status` enum('pending','paid','refunded','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'สถานะการชำระเงิน',
  `payment_hold_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `payment_hold_released_at` timestamp NULL DEFAULT NULL,
  `payment_transaction_id` bigint unsigned DEFAULT NULL,
  `provider_notified_at` datetime DEFAULT NULL COMMENT 'เวลาที่แจ้งเตือน provider',
  `provider_response_deadline` datetime DEFAULT NULL COMMENT 'deadline ตอบกลับ (เช่น 15 นาที)',
  `provider_viewed_at` datetime DEFAULT NULL COMMENT 'provider เปิดดูเมื่อไร',
  `provider_accepted_at` datetime DEFAULT NULL COMMENT 'เวลาที่รับงาน',
  `provider_rejected_at` datetime DEFAULT NULL COMMENT 'เวลาที่ปฏิเสธ',
  `provider_rejected_reason` text COLLATE utf8mb4_unicode_ci COMMENT 'เหตุผลที่ปฏิเสธ',
  `provider_response_minutes` int DEFAULT NULL COMMENT 'ใช้เวลาตอบกลับกี่นาที',
  `status` enum('pending','paid','notifying_provider','waiting_provider','provider_accepted','provider_rejected','provider_on_way','in_progress','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'สถานะการจอง',
  `customer_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'หมายเหตุจากลูกค้า',
  `provider_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'หมายเหตุจาก provider',
  `admin_notes` text COLLATE utf8mb4_unicode_ci COMMENT 'หมายเหตุจาก admin',
  `cancellation_reason` text COLLATE utf8mb4_unicode_ci COMMENT 'เหตุผลการยกเลิก',
  `cancelled_by_type` enum('user','provider','system','admin') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancellation_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `cancellation_fee_charged` tinyint(1) NOT NULL DEFAULT '0',
  `cancelled_at` datetime DEFAULT NULL COMMENT 'เวลาที่ยกเลิก',
  `cancelled_by` enum('customer','provider','admin','system') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ยกเลิกโดย',
  `confirmed_at` datetime DEFAULT NULL COMMENT 'เวลาที่ยืนยัน',
  `started_at` datetime DEFAULT NULL COMMENT 'เวลาเริ่มให้บริการ',
  `completed_at` datetime DEFAULT NULL COMMENT 'เวลาเสร็จสิ้น',
  `commission_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'คอมมิชชั่น MLM',
  `platform_fee_percentage` decimal(5,2) NOT NULL DEFAULT '10.00' COMMENT 'เปอร์เซ็นต์ค่าแพลตฟอร์ม (snapshot ณ เวลาจอง)',
  `platform_fee_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'จำนวนเงินค่าแพลตฟอร์ม (บาท)',
  `provider_pv_percentage` decimal(5,2) NOT NULL DEFAULT '5.00' COMMENT 'เปอร์เซ็นต์ PV/การตลาด (snapshot ณ เวลาจอง)',
  `provider_pv_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'จำนวนเงิน PV (บาท)',
  `provider_earnings` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'รายได้สุทธิของ Provider = total - platform_fee - pv',
  `system_revenue` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'รายได้รวมของระบบ = platform_fee + pv',
  `mlm_member_id` bigint unsigned DEFAULT NULL,
  `metadata` json DEFAULT NULL COMMENT 'ข้อมูลเพิ่มเติม (JSON)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `vat_percentage` decimal(5,2) NOT NULL DEFAULT '7.00' COMMENT '% VAT (snapshot)',
  `vat_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'จำนวน VAT (บาท)',
  `cashback_percentage` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '% Cashback (snapshot)',
  `cashback_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'จำนวน Cashback (บาท)',
  `mlm_pv_total` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'PV รวม (สำหรับ MLM Commission)',
  `mlm_commission_total` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าคอม MLM รวม',
  `rating` tinyint DEFAULT NULL COMMENT 'คะแนน 1-5 ดาว',
  `review` text COLLATE utf8mb4_unicode_ci COMMENT 'ความคิดเห็นจากลูกค้า',
  `rated_at` datetime DEFAULT NULL COMMENT 'เวลาที่ให้คะแนน',
  `final_price` decimal(10,2) DEFAULT NULL COMMENT 'ราคาสุดท้ายหลังส่วนลด',
  `user_live_latitude` decimal(10,8) DEFAULT NULL,
  `user_live_longitude` decimal(11,8) DEFAULT NULL,
  `user_location_updated_at` timestamp NULL DEFAULT NULL,
  `evidence_photos` json DEFAULT NULL COMMENT 'รูปหลักฐานก่อน/หลังบริการ',
  `service_started_photo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รูปเมื่อเริ่มบริการ',
  `service_completed_photo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'รูปเมื่อเสร็จบริการ',
  `is_suspicious` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'มีพฤติกรรมน่าสงสัย',
  `suspicious_flags` json DEFAULT NULL COMMENT 'รายละเอียดพฤติกรรมน่าสงสัย',
  `requires_photo_evidence` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ต้องถ่ายรูปหลักฐาน',
  PRIMARY KEY (`id`),
  UNIQUE KEY `service_bookings_booking_number_unique` (`booking_number`),
