CREATE TABLE `video_auto_schedules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `template_id` bigint unsigned DEFAULT NULL COMMENT 'เทมเพลตที่ใช้',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อตารางเวลา',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'คำอธิบาย',
  `frequency_type` enum('once','daily','weekly','monthly','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `run_at` timestamp NULL DEFAULT NULL COMMENT 'เวลาที่จะรัน (once)',
  `daily_time` time DEFAULT NULL COMMENT 'เวลาที่จะรันทุกวัน',
  `weekly_days` json DEFAULT NULL COMMENT 'วันในสัปดาห์ [0=อาทิตย์, 1=จันทร์, ...]',
  `weekly_time` time DEFAULT NULL COMMENT 'เวลาที่จะรัน',
  `monthly_days` json DEFAULT NULL COMMENT 'วันที่ในเดือน [1, 15, 28]',
  `monthly_time` time DEFAULT NULL COMMENT 'เวลาที่จะรัน',
  `cron_expression` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Cron expression',
  `timezone` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Asia/Bangkok' COMMENT 'Timezone',
  `videos_per_run` int unsigned NOT NULL DEFAULT '1' COMMENT 'จำนวนวีดีโอที่สร้างต่อครั้ง',
  `randomize_content` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'สุ่มเนื้อหาหรือไม่',
  `content_variations` json DEFAULT NULL COMMENT 'รูปแบบเนื้อหาที่หมุนเวียน',
  `auto_publish` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'โพสอัตโนมัติหรือไม่',
  `publish_delay` int unsigned NOT NULL DEFAULT '0' COMMENT 'หน่วงโพสกี่นาทีหลังสร้างเสร็จ',
  `publish_platforms` json DEFAULT NULL COMMENT 'Platforms ที่จะโพส',
  `stagger_publishing` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'โพสทีละ platform',
  `stagger_interval` int unsigned NOT NULL DEFAULT '30' COMMENT 'ระยะห่างระหว่าง platform (นาที)',
  `max_videos_per_day` int unsigned DEFAULT NULL COMMENT 'จำกัดวีดีโอต่อวัน',
  `max_videos_per_week` int unsigned DEFAULT NULL COMMENT 'จำกัดวีดีโอต่อสัปดาห์',
  `max_videos_per_month` int unsigned DEFAULT NULL COMMENT 'จำกัดวีดีโอต่อเดือน',
  `max_total_videos` int unsigned DEFAULT NULL COMMENT 'จำกัดวีดีโอทั้งหมด',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `last_run_at` timestamp NULL DEFAULT NULL COMMENT 'รันครั้งล่าสุด',
  `next_run_at` timestamp NULL DEFAULT NULL COMMENT 'รันครั้งต่อไป',
  `run_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'จำนวนครั้งที่รัน',
  `success_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'รันสำเร็จ',
  `fail_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'รันล้มเหลว',
  `valid_from` date DEFAULT NULL COMMENT 'เริ่มใช้งานวันที่',
  `valid_until` date DEFAULT NULL COMMENT 'หมดอายุวันที่',
  `pause_on_error` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'หยุดเมื่อเกิด error',
  `consecutive_failures` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'ล้มเหลวติดต่อกัน',
  `max_consecutive_failures` tinyint unsigned NOT NULL DEFAULT '3' COMMENT 'ล้มเหลวติดต่อกันสูงสุด',
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vas_active_next_idx` (`is_active`,`next_run_at`),
  KEY `vas_freq_active_idx` (`frequency_type`,`is_active`),
  KEY `video_auto_schedules_template_id_foreign` (`template_id`),
  KEY `video_auto_schedules_created_by_foreign` (`created_by`),
  KEY `video_auto_schedules_is_active_index` (`is_active`),
  KEY `video_auto_schedules_next_run_at_index` (`next_run_at`),
  CONSTRAINT `video_auto_schedules_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `video_auto_schedules_template_id_foreign` FOREIGN KEY (`template_id`) REFERENCES `video_auto_templates` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
